"""Derivatives of the Triton kernels of the classical force fields (OPLS, AMBER, CHARMM, DREIDING)

Generated by ``tools/generate_amoeba_derivatives.py --target classical`` (do not edit by hand; regenerate).
``<kernel>_t`` is the tangent of a kernel along the positions (loads of ``pos_ptr`` carry the tangents
``pos_ptr_t``, its outputs write their tangents to ``<output>_t``); ``<kernel>_r`` is the adjoint of a
forward kernel with respect to its parameter arrays (their gradients into ``<param>_g`` from the incoming
gradients of the energies); ``<kernel>_r_t`` is that adjoint's tangent along the positions.
"""
# ruff: noqa: E501, F841
import triton
import triton.language as tl
from triton.language.extra import libdevice

from .classical_kernels import (
    _add_sorted,
    _angle,
    _bond,
    _cross,
    _excluded_row,
    _hbond,
    _inversion,
    _morse,
    _pair,
    _pair_energy,
    _segments,
    _switch,
    _torsion,
    _vec,
)


@triton.jit
def _vec_t_200000000(pos_ptr, cell_ptr, bat_ptr, s_ptr, a, b, e, m, HAS_CELL: tl.constexpr, pos_ptr_t):
    """Tangent of ``_vec`` along the arguments pos_ptr."""
    x = tl.load(pos_ptr + b * 3, mask=m, other=0.0) - tl.load(pos_ptr + a * 3, mask=m, other=0.0)
    x_t = tl.load(pos_ptr_t + b * 3, mask=m, other=0.0) - tl.load(pos_ptr_t + a * 3, mask=m, other=0.0)
    y = tl.load(pos_ptr + b * 3 + 1, mask=m, other=0.0) - tl.load(pos_ptr + a * 3 + 1, mask=m, other=0.0)
    y_t = tl.load(pos_ptr_t + b * 3 + 1, mask=m, other=0.0) - tl.load(pos_ptr_t + a * 3 + 1, mask=m, other=0.0)
    z = tl.load(pos_ptr + b * 3 + 2, mask=m, other=0.0) - tl.load(pos_ptr + a * 3 + 2, mask=m, other=0.0)
    z_t = tl.load(pos_ptr_t + b * 3 + 2, mask=m, other=0.0) - tl.load(pos_ptr_t + a * 3 + 2, mask=m, other=0.0)
    if HAS_CELL:
        s0 = tl.load(s_ptr + e * 3, mask=m, other=0.0)
        s1 = tl.load(s_ptr + e * 3 + 1, mask=m, other=0.0)
        s2 = tl.load(s_ptr + e * 3 + 2, mask=m, other=0.0)
        if HAS_CELL == 2:
            x += s0 * tl.load(cell_ptr) + s1 * tl.load(cell_ptr + 3) + s2 * tl.load(cell_ptr + 6)
            y += s0 * tl.load(cell_ptr + 1) + s1 * tl.load(cell_ptr + 4) + s2 * tl.load(cell_ptr + 7)
            z += s0 * tl.load(cell_ptr + 2) + s1 * tl.load(cell_ptr + 5) + s2 * tl.load(cell_ptr + 8)
        else:
            c = tl.load(bat_ptr + a, mask=m, other=0).to(tl.int64) * 9
            x += s0 * tl.load(cell_ptr + c, mask=m, other=0.0) + s1 * tl.load(cell_ptr + c + 3, mask=m, other=0.0) + s2 * tl.load(cell_ptr + c + 6, mask=m, other=0.0)
            y += s0 * tl.load(cell_ptr + c + 1, mask=m, other=0.0) + s1 * tl.load(cell_ptr + c + 4, mask=m, other=0.0) + s2 * tl.load(cell_ptr + c + 7, mask=m, other=0.0)
            z += s0 * tl.load(cell_ptr + c + 2, mask=m, other=0.0) + s1 * tl.load(cell_ptr + c + 5, mask=m, other=0.0) + s2 * tl.load(cell_ptr + c + 8, mask=m, other=0.0)
    return (x, y, z, x_t, y_t, z_t)


@triton.jit
def _pair_energy_t_100000000(r2, t_ptr, tab_ptr, qi, qk, ke, tiny, m, FORM: tl.constexpr, r2_t):
    """Tangent of ``_pair_energy`` along the arguments r2."""
    if FORM == 0:
        A = tl.load(tab_ptr + t_ptr * 3, mask=m, other=0.0)
        Bc = tl.load(tab_ptr + t_ptr * 3 + 1, mask=m, other=0.0)
        R2 = tl.load(tab_ptr + t_ptr * 3 + 2, mask=m, other=0.0)
        inv = 1.0 / (r2 + tiny)
        inv_t = -(1.0 / (r2 + tiny) * r2_t / (r2 + tiny))
        y = R2 * inv
        y_t = R2 * inv_t
        x = y * y * y
        x_t = (y_t * y + y * y_t) * y + y * y * y_t
        e_v = A * (x * x - Bc * x)
        e_v_t = A * (x_t * x + x * x_t - Bc * x_t)
        de_v = A * (2.0 * x - Bc) * (-3.0 * x * inv)
        de_v_t = A * (2.0 * x_t) * (-3.0 * x * inv) + A * (2.0 * x - Bc) * (-3.0 * x_t * inv + -3.0 * x * inv_t)
    else:
        a = tl.load(tab_ptr + t_ptr * 3, mask=m, other=0.0)
        b = tl.load(tab_ptr + t_ptr * 3 + 1, mask=m, other=0.0)
        c = tl.load(tab_ptr + t_ptr * 3 + 2, mask=m, other=0.0)
        r = tl.sqrt(r2 + tiny)
        r_t = 0.5 * r2_t / tl.sqrt(r2 + tiny)
        ex = a * tl.exp(-c * r)
        ex_t = a * (tl.exp(-c * r) * (-c * r_t))
        r6 = r2 * r2 * r2
        r6_t = (r2_t * r2 + r2 * r2_t) * r2 + r2 * r2 * r2_t
        e_v = ex - b / (r6 + tiny)
        e_v_t = ex_t - -(b / (r6 + tiny) * r6_t / (r6 + tiny))
        de_v = -c * ex * 0.5 / r + b * 3.0 * r2 * r2 / ((r6 + tiny) * (r6 + tiny))
        de_v_t = -c * ex_t * 0.5 / r - -c * ex * 0.5 / r * r_t / r + ((b * 3.0 * r2_t * r2 + b * 3.0 * r2 * r2_t) / ((r6 + tiny) * (r6 + tiny)) - b * 3.0 * r2 * r2 / ((r6 + tiny) * (r6 + tiny)) * (r6_t * (r6 + tiny) + (r6 + tiny) * r6_t) / ((r6 + tiny) * (r6 + tiny)))
    inv_c = 1.0 / (r2 + tiny)
    inv_c_t = -(1.0 / (r2 + tiny) * r2_t / (r2 + tiny))
    e_c = ke * qi * qk * tl.sqrt(inv_c)
    e_c_t = ke * qi * qk * (0.5 * inv_c_t / tl.sqrt(inv_c))
    de_c = -0.5 * e_c * inv_c
    de_c_t = -0.5 * e_c_t * inv_c + -0.5 * e_c * inv_c_t
    return (e_v, de_v, e_c, de_c, e_v_t, de_v_t, e_c_t, de_c_t)


@triton.jit
def _switch_t_1000(r, start, inv_width, SWITCH: tl.constexpr, r_t):
    """Tangent of ``_switch`` along the arguments r."""
    if SWITCH:
        x = tl.minimum(tl.maximum((r - start) * inv_width, 0.0), 1.0)
        x_t = tl.where(tl.maximum((r - start) * inv_width, 0.0) < 1.0, tl.where((r - start) * inv_width > 0.0, r_t * inv_width, tl.where(0.0 > (r - start) * inv_width, 0.0, 0.5 * (r_t * inv_width + 0.0))), tl.where(1.0 < tl.maximum((r - start) * inv_width, 0.0), 0.0, 0.5 * (tl.where((r - start) * inv_width > 0.0, r_t * inv_width, tl.where(0.0 > (r - start) * inv_width, 0.0, 0.5 * (r_t * inv_width + 0.0))) + 0.0)))
        s = 1.0 - x * x * x * (10.0 - 15.0 * x + 6.0 * x * x)
        s_t = -(((x_t * x + x * x_t) * x + x * x * x_t) * (10.0 - 15.0 * x + 6.0 * x * x) + x * x * x * (-(15.0 * x_t) + (6.0 * x_t * x + 6.0 * x * x_t)))
        ds = -30.0 * x * x * (1.0 - x) * (1.0 - x) * inv_width
        ds_t = (((-30.0 * x_t * x + -30.0 * x * x_t) * (1.0 - x) + -30.0 * x * x * -x_t) * (1.0 - x) + -30.0 * x * x * (1.0 - x) * -x_t) * inv_width
    else:
        s = r * 0.0 + 1.0
        s_t = s * 0.0
        ds = r * 0.0
        ds_t = ds * 0.0
    return (s, ds, s_t, ds_t)


@triton.jit
def _pair_t_0002000000000000000000(src_ptr, dst_ptr, sh_ptr, pos_ptr, cell_ptr, bat_ptr, xp_ptr, xk_ptr, t_ptr, q_ptr, tab_ptr, sc_ptr, e, m0, n_local, n_types, DT: tl.constexpr, HAS_CELL: tl.constexpr, EXCL: tl.constexpr, MAXE: tl.constexpr, FORM: tl.constexpr, SWITCH: tl.constexpr, pos_ptr_t):
    """Tangent of ``_pair`` along the arguments pos_ptr."""
    i = tl.load(src_ptr + e, mask=m0, other=0).to(tl.int64)
    k = tl.load(dst_ptr + e, mask=m0, other=0).to(tl.int64)
    m = m0 & (i <= k)
    (x, y, z, x_t, y_t, z_t) = _vec_t_200000000(pos_ptr, cell_ptr, bat_ptr, sh_ptr, i, k, e, m, HAS_CELL, pos_ptr_t)
    x = x.to(DT)
    x_t = x_t.to(DT)
    y = y.to(DT)
    y_t = y_t.to(DT)
    z = z.to(DT)
    z_t = z_t.to(DT)
    r2 = x * x + y * y + z * z
    r2_t = x_t * x + x * x_t + (y_t * y + y * y_t) + (z_t * z + z * z_t)
    own = i == k
    m = m & (~own | (r2 > 0.0))
    ke = tl.load(sc_ptr).to(DT)
    tiny = tl.load(sc_ptr + 1).to(DT)
    cut2 = tl.load(sc_ptr + 2).to(DT)
    start = tl.load(sc_ptr + 3).to(DT)
    inv_width = tl.load(sc_ptr + 4).to(DT)
    m = m & (r2 < cut2)
    w = tl.where(m, tl.where(own, 0.5, 1.0), 0.0).to(DT)
    if EXCL:
        hit = _excluded_row(xp_ptr, xk_ptr, i % n_local, (k % n_local).to(tl.int32), m, MAXE)
        w = tl.where(hit, 0.0, w).to(DT)
    tp = tl.load(t_ptr + i, mask=m, other=0) * n_types + tl.load(t_ptr + k, mask=m, other=0)
    qi = tl.load(q_ptr + i, mask=m, other=0.0)
    qk = tl.load(q_ptr + k, mask=m, other=0.0)
    (e_v, de_v, e_c, de_c, e_v_t, de_v_t, e_c_t, de_c_t) = _pair_energy_t_100000000(r2, tp, tab_ptr, qi, qk, ke, tiny, m, FORM, r2_t)
    r = tl.sqrt(r2 + tiny)
    r_t = 0.5 * r2_t / tl.sqrt(r2 + tiny)
    (s, ds, s_t, ds_t) = _switch_t_1000(r, start, inv_width, SWITCH, r_t)
    if SWITCH:
        dsr = ds * 0.5 / r
        dsr_t = ds_t * 0.5 / r - ds * 0.5 / r * r_t / r
    else:
        dsr = ds
        dsr_t = ds_t
    return (i, k, m, x, y, z, w * s * e_v, w * (s * de_v + e_v * dsr), w * s * e_c, w * (s * de_c + e_c * dsr), x_t, y_t, z_t, w * s_t * e_v + w * s * e_v_t, w * (s_t * de_v + s * de_v_t + (e_v_t * dsr + e_v * dsr_t)), w * s_t * e_c + w * s * e_c_t, w * (s_t * de_c + s * de_c_t + (e_c_t * dsr + e_c * dsr_t)))


@triton.jit
def _pairs_forward_t(src_ptr, dst_ptr, sh_ptr, pos_ptr, cell_ptr, bat_ptr, xp_ptr, xk_ptr, t_ptr, q_ptr, tab_ptr, sc_ptr, e_ptr, n_edges, n_local, n_types, pos_ptr_t, e_ptr_t, DT: tl.constexpr, HAS_CELL: tl.constexpr, EXCL: tl.constexpr, MAXE: tl.constexpr, FORM: tl.constexpr, SWITCH: tl.constexpr, BLOCK: tl.constexpr):
    """Tangent of the kernel ``_pairs_forward``: tangents read and written through ``pos_ptr_t``, ``e_ptr_t``."""
    e = (tl.program_id(0) * BLOCK + tl.arange(0, BLOCK)).to(tl.int64)
    (i, k, m, _, _, _, ev, _, ec, _, __t, __t, __t, ev_t, __t, ec_t, __t) = _pair_t_0002000000000000000000(src_ptr, dst_ptr, sh_ptr, pos_ptr, cell_ptr, bat_ptr, xp_ptr, xk_ptr, t_ptr, q_ptr, tab_ptr, sc_ptr, e, e < n_edges, n_local, n_types, DT, HAS_CELL, EXCL, MAXE, FORM, SWITCH, pos_ptr_t)
    hv = (0.5 * ev).to(tl.float64)
    hv_t = (0.5 * ev_t).to(tl.float64)
    hc = (0.5 * ec).to(tl.float64)
    hc_t = (0.5 * ec_t).to(tl.float64)
    (i0, i1, same, tail, rest) = _segments(src_ptr, i, m, n_edges, BLOCK)
    _add_sorted(e_ptr, i0 * 2, i1 * 2, i * 2, hv, same, tail, rest, TAIL=1)
    _add_sorted(e_ptr_t, i0 * 2, i1 * 2, i * 2, hv_t, same, tail, rest, TAIL=1)
    _add_sorted(e_ptr + 1, i0 * 2, i1 * 2, i * 2, hc, same, tail, rest, TAIL=1)
    _add_sorted(e_ptr_t + 1, i0 * 2, i1 * 2, i * 2, hc_t, same, tail, rest, TAIL=1)
    tl.atomic_add(e_ptr + k * 2, hv, mask=m, sem='relaxed')
    tl.atomic_add(e_ptr_t + k * 2, hv_t, mask=m, sem='relaxed')
    tl.atomic_add(e_ptr + k * 2 + 1, hc, mask=m, sem='relaxed')
    tl.atomic_add(e_ptr_t + k * 2 + 1, hc_t, mask=m, sem='relaxed')


@triton.jit
def _bond_t_2000000000000(pos_ptr, cell_ptr, bat_ptr, s_ptr, idx_ptr, k_ptr, r0_ptr, e, m, n_terms, tiny, DT: tl.constexpr, HAS_CELL: tl.constexpr, pos_ptr_t):
    """Tangent of ``_bond`` along the arguments pos_ptr."""
    a = tl.load(idx_ptr + e, mask=m, other=0).to(tl.int64)
    b = tl.load(idx_ptr + n_terms + e, mask=m, other=0).to(tl.int64)
    (x, y, z, x_t, y_t, z_t) = _vec_t_200000000(pos_ptr, cell_ptr, bat_ptr, s_ptr, a, b, e, m, HAS_CELL, pos_ptr_t)
    x = x.to(DT)
    x_t = x_t.to(DT)
    y = y.to(DT)
    y_t = y_t.to(DT)
    z = z.to(DT)
    z_t = z_t.to(DT)
    r = tl.sqrt(x * x + y * y + z * z + tiny)
    r_t = 0.5 * (x_t * x + x * x_t + (y_t * y + y * y_t) + (z_t * z + z * z_t)) / tl.sqrt(x * x + y * y + z * z + tiny)
    k = tl.load(k_ptr + e, mask=m, other=0.0)
    dr = r - tl.load(r0_ptr + e, mask=m, other=0.0)
    dr_t = r_t
    d = 2.0 * k * dr / r
    d_t = 2.0 * k * dr_t / r - 2.0 * k * dr / r * r_t / r
    return (a, b, k * dr * dr, d * x, d * y, d * z, k * dr_t * dr + k * dr * dr_t, d_t * x + d * x_t, d_t * y + d * y_t, d_t * z + d * z_t)


@triton.jit
def _bonds_forward_t(pos_ptr, cell_ptr, bat_ptr, s_ptr, idx_ptr, k_ptr, r0_ptr, sc_ptr, out_ptr, n_terms, pos_ptr_t, out_ptr_t, DT: tl.constexpr, HAS_CELL: tl.constexpr, BLOCK: tl.constexpr):
    """Tangent of the kernel ``_bonds_forward``: tangents read and written through ``pos_ptr_t``, ``out_ptr_t``."""
    e = (tl.program_id(0) * BLOCK + tl.arange(0, BLOCK)).to(tl.int64)
    m = e < n_terms
    tiny = tl.load(sc_ptr).to(DT)
    (a, b, en, _, _, _, en_t, __t, __t, __t) = _bond_t_2000000000000(pos_ptr, cell_ptr, bat_ptr, s_ptr, idx_ptr, k_ptr, r0_ptr, e, m, n_terms, tiny, DT, HAS_CELL, pos_ptr_t)
    h = (0.5 * en).to(tl.float64)
    h_t = (0.5 * en_t).to(tl.float64)
    tl.atomic_add(out_ptr + a, h, mask=m, sem='relaxed')
    tl.atomic_add(out_ptr_t + a, h_t, mask=m, sem='relaxed')
    tl.atomic_add(out_ptr + b, h, mask=m, sem='relaxed')
    tl.atomic_add(out_ptr_t + b, h_t, mask=m, sem='relaxed')


@triton.jit
def _morse_t_20000000000000(pos_ptr, cell_ptr, bat_ptr, s_ptr, idx_ptr, d_ptr, al_ptr, r0_ptr, e, m, n_terms, tiny, DT: tl.constexpr, HAS_CELL: tl.constexpr, pos_ptr_t):
    """Tangent of ``_morse`` along the arguments pos_ptr."""
    a = tl.load(idx_ptr + e, mask=m, other=0).to(tl.int64)
    b = tl.load(idx_ptr + n_terms + e, mask=m, other=0).to(tl.int64)
    (x, y, z, x_t, y_t, z_t) = _vec_t_200000000(pos_ptr, cell_ptr, bat_ptr, s_ptr, a, b, e, m, HAS_CELL, pos_ptr_t)
    x = x.to(DT)
    x_t = x_t.to(DT)
    y = y.to(DT)
    y_t = y_t.to(DT)
    z = z.to(DT)
    z_t = z_t.to(DT)
    r = tl.sqrt(x * x + y * y + z * z + tiny)
    r_t = 0.5 * (x_t * x + x * x_t + (y_t * y + y * y_t) + (z_t * z + z * z_t)) / tl.sqrt(x * x + y * y + z * z + tiny)
    dd = tl.load(d_ptr + e, mask=m, other=0.0)
    al = tl.load(al_ptr + e, mask=m, other=0.0)
    ex = tl.exp(-al * (r - tl.load(r0_ptr + e, mask=m, other=0.0)))
    ex_t = tl.exp(-al * (r - tl.load(r0_ptr + e, mask=m, other=0.0))) * (-al * r_t)
    f = ex - 1.0
    f_t = ex_t
    d = -2.0 * dd * al * ex * f / r
    d_t = (-2.0 * dd * al * ex_t * f + -2.0 * dd * al * ex * f_t) / r - -2.0 * dd * al * ex * f / r * r_t / r
    return (a, b, dd * f * f, d * x, d * y, d * z, dd * f_t * f + dd * f * f_t, d_t * x + d * x_t, d_t * y + d * y_t, d_t * z + d * z_t)


@triton.jit
def _morses_forward_t(pos_ptr, cell_ptr, bat_ptr, s_ptr, idx_ptr, d_ptr, al_ptr, r0_ptr, sc_ptr, out_ptr, n_terms, pos_ptr_t, out_ptr_t, DT: tl.constexpr, HAS_CELL: tl.constexpr, BLOCK: tl.constexpr):
    """Tangent of the kernel ``_morses_forward``: tangents read and written through ``pos_ptr_t``, ``out_ptr_t``."""
