@triton.jit
def _angle_t_200000000000000(pos_ptr, cell_ptr, bat_ptr, s_ptr, idx_ptr, st_ptr, k_ptr, x0_ptr, e, m, n_terms, tiny, bound, DT: tl.constexpr, HAS_CELL: tl.constexpr, pos_ptr_t):
    """Tangent of ``_angle`` along the arguments pos_ptr."""
    a = tl.load(idx_ptr + e, mask=m, other=0).to(tl.int64)
    c = tl.load(idx_ptr + n_terms + e, mask=m, other=0).to(tl.int64)
    b = tl.load(idx_ptr + 2 * n_terms + e, mask=m, other=0).to(tl.int64)
    (ux, uy, uz, ux_t, uy_t, uz_t) = _vec_t_200000000(pos_ptr, cell_ptr, bat_ptr, s_ptr, c, a, e, m, HAS_CELL, pos_ptr_t)
    (vx, vy, vz, vx_t, vy_t, vz_t) = _vec_t_200000000(pos_ptr, cell_ptr, bat_ptr, s_ptr + n_terms * 3, c, b, e, m, HAS_CELL, pos_ptr_t)
    ux = ux.to(DT)
    ux_t = ux_t.to(DT)
    uy = uy.to(DT)
    uy_t = uy_t.to(DT)
    uz = uz.to(DT)
    uz_t = uz_t.to(DT)
    vx = vx.to(DT)
    vx_t = vx_t.to(DT)
    vy = vy.to(DT)
    vy_t = vy_t.to(DT)
    vz = vz.to(DT)
    vz_t = vz_t.to(DT)
    uu = ux * ux + uy * uy + uz * uz
    uu_t = ux_t * ux + ux * ux_t + (uy_t * uy + uy * uy_t) + (uz_t * uz + uz * uz_t)
    vv = vx * vx + vy * vy + vz * vz
    vv_t = vx_t * vx + vx * vx_t + (vy_t * vy + vy * vy_t) + (vz_t * vz + vz * vz_t)
    p = ux * vx + uy * vy + uz * vz
    p_t = ux_t * vx + ux * vx_t + (uy_t * vy + uy * vy_t) + (uz_t * vz + uz * vz_t)
    d = tl.sqrt(uu * vv + tiny)
    d_t = 0.5 * (uu_t * vv + uu * vv_t) / tl.sqrt(uu * vv + tiny)
    cs = p / d
